import React, { useEffect, useState } from "react"
import { StyleSheet, Text, View } from "react-native"

import { theme } from "../../shared/theme"

type Cue = { start: number; end: number; text: string }

// Tiny WebVTT parser — handles the common shape (WEBVTT header, blank-line
// separated cues, "00:00.000 --> 00:00.000" timestamps with optional hours,
// multi-line text). Cue settings, voice tags, NOTE blocks are preserved as
// plain text rather than parsed; that's enough for the academy use case
// (uploaded VTT generated by Whisper / hand-edited from SRT).
const TS_RE =
  /^(\d{1,2}:)?(\d{1,2}):(\d{1,2})[.,](\d{1,3})\s+-->\s+(\d{1,2}:)?(\d{1,2}):(\d{1,2})[.,](\d{1,3})/

const toSeconds = (parts: {
  h?: string
  m: string
  s: string
  ms: string
}): number => {
  const h = parts.h ? parseInt(parts.h.replace(":", ""), 10) : 0
  const m = parseInt(parts.m, 10)
  const s = parseInt(parts.s, 10)
  const ms = parseInt(parts.ms.padEnd(3, "0").slice(0, 3), 10)
  return h * 3600 + m * 60 + s + ms / 1000
}

export const parseVtt = (raw: string): Cue[] => {
  const cues: Cue[] = []
  // Strip BOM and unify line endings; split on a blank line so each block
  // is a separate cue chunk.
  const cleaned = raw.replace(/^﻿/, "").replace(/\r/g, "")
  const blocks = cleaned.split(/\n\n+/)
  for (const block of blocks) {
    const lines = block.split("\n").filter((line) => line.length > 0)
    if (lines.length === 0) continue
    // First or second line carries the timestamps. The optional first line
    // is a cue identifier we don't render.
    const tsLine = lines.find((line) => TS_RE.test(line))
    if (!tsLine) continue
    const match = TS_RE.exec(tsLine)
    if (!match) continue
    const start = toSeconds({
      h: match[1],
      m: match[2],
      s: match[3],
      ms: match[4],
    })
    const end = toSeconds({
      h: match[5],
      m: match[6],
      s: match[7],
      ms: match[8],
    })
    const tsIdx = lines.indexOf(tsLine)
    const text = lines
      .slice(tsIdx + 1)
      .join("\n")
      .replace(/<[^>]+>/g, "") // drop HTML tags (e.g. <c>, <i>)
      .trim()
    if (text) cues.push({ start, end, text })
  }
  return cues
}

const findActiveCue = (cues: Cue[], t: number): Cue | null => {
  // Linear scan is fine here — a typical lesson VTT has under 1k cues and
  // we only hit this on the 250ms tick. Switching to binary search adds
  // complexity for a workload that hasn't shown up.
  for (const cue of cues) {
    if (t >= cue.start && t <= cue.end) return cue
  }
  return null
}

type Props = {
  url: string
  getCurrentTime: () => number | undefined
}

export function SubtitleOverlay({ url, getCurrentTime }: Props) {
  const [cues, setCues] = useState<Cue[] | null>(null)
  const [active, setActive] = useState<Cue | null>(null)

  useEffect(() => {
    let cancelled = false
    setCues(null)
    setActive(null)
    void fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error(`subtitle fetch ${res.status}`)
        return res.text()
      })
      .then((text) => {
        if (cancelled) return
        setCues(parseVtt(text))
      })
      .catch(() => {
        if (cancelled) return
        setCues([])
      })
    return () => {
      cancelled = true
    }
  }, [url])

  useEffect(() => {
    if (!cues || cues.length === 0) return
    const interval = setInterval(() => {
      const t = getCurrentTime()
      if (typeof t !== "number") return
      const next = findActiveCue(cues, t)
      setActive((prev) => (prev?.text === next?.text ? prev : next))
    }, 250)
    return () => clearInterval(interval)
  }, [cues, getCurrentTime])

  if (!active) return null
  return (
    <View style={styles.wrap} pointerEvents="none">
      <Text style={styles.text}>{active.text}</Text>
    </View>
  )
}

const styles = StyleSheet.create({
  wrap: {
    position: "absolute",
    bottom: theme.spacing(3),
    left: theme.spacing(3),
    right: theme.spacing(3),
    alignItems: "center",
  },
  text: {
    backgroundColor: "rgba(0,0,0,0.65)",
    color: "#fff",
    paddingHorizontal: theme.spacing(2),
    paddingVertical: theme.spacing(1),
    borderRadius: theme.radius.sm,
    fontSize: 16,
    textAlign: "center",
    overflow: "hidden",
  },
})
